// M-11 · Synchro-Compur 0-MXV: a leaf shutter of 29 parts, from the repair manual.
// Every part is drawn where it sits at the dynamics' reference: blades shut, the cam
// with its opening lug on the stud. The Render view plays one 1/125 release from the
// shutter's own planar dynamics (compur-poses.look.js), not from a jig study.
// Generated by the Compur project's cad/build.mjs from cad/parts.mjs; M-11 adds the
// materials the comments name and a finish where a colour says the metal is coated.
const parts = await importPartFile('compur.parts.js')
return j.assembly('Synchro-Compur 0-MXV')
  .add('housing', parts.housing(), { ground: true })
  .add('tube', parts.tube(), { at: j.tx.move(0, 0, 0) })
  .add('base', parts.base(), { at: j.tx.move(0, 0, 0) })
  .add('bladePlate', parts.bladePlate(), { at: j.tx.move(0, 0, 0) })
  .add('blade1', parts.blade1())
  .add('blade2', parts.blade2())
  .add('blade3', parts.blade3())
  .add('blade4', parts.blade4())
  .add('blade5', parts.blade5())
  .add('ring', parts.ring())
  .add('cam', parts.cam())
  .add('pinion', parts.pinion())
  .add('cockingRing', parts.cockingRing())
  .add('latch', parts.latch())
  .add('release', parts.release(), { at: j.tx.move(0, 0, 0) })
  .add('bridge', parts.bridge(), { at: j.tx.move(0, 0, 0) })
  .add('retard', parts.retard())
  .add('segment', parts.segment())
  .add('weight', parts.weight())
  .add('w1', parts.w1())
  .add('w2', parts.w2())
  .add('star', parts.star())
  .add('pallet', parts.pallet())
  .add('carrier', parts.carrier())
  .add('escPlates', parts.escPlates(), { at: j.tx.move(0, 0, 0) })
  .add('speedCam', parts.speedCam(), { at: j.tx.move(0, 0, 0) })
  .add('speedRing', parts.speedRing(), { at: j.tx.move(0, 0, 0) })
  .add('cover', parts.cover(), { at: j.tx.move(0, 0, 0) })
  .add('iris', parts.iris(), { at: j.tx.move(0, 0, 0) })
  .joint('ring', j.joint.revolute(), 'tube:ringPivot', 'ring:pivot')
  .joint('cockingRing', j.joint.revolute(), 'tube:cockingRingPivot', 'cockingRing:pivot')
  .joint('cam', j.joint.revolute(), 'base:camPivot', 'cam:pivot')
  .joint('pinion', j.joint.revolute(), 'base:pinionPivot', 'pinion:pivot')
  .joint('blade1', j.joint.revolute(), 'base:blade1Pivot', 'blade1:pivot')
  .joint('blade2', j.joint.revolute(), 'base:blade2Pivot', 'blade2:pivot')
  .joint('blade3', j.joint.revolute(), 'base:blade3Pivot', 'blade3:pivot')
  .joint('blade4', j.joint.revolute(), 'base:blade4Pivot', 'blade4:pivot')
  .joint('blade5', j.joint.revolute(), 'base:blade5Pivot', 'blade5:pivot')
  .joint('retard', j.joint.revolute(), 'escPlates:retardPivot', 'retard:pivot')
  .joint('segment', j.joint.revolute(), 'escPlates:segmentPivot', 'segment:pivot')
  .joint('weight', j.joint.revolute(), 'escPlates:weightPivot', 'weight:pivot')
  .joint('w1', j.joint.revolute(), 'escPlates:w1Pivot', 'w1:pivot')
  .joint('w2', j.joint.revolute(), 'escPlates:w2Pivot', 'w2:pivot')
  .joint('star', j.joint.revolute(), 'escPlates:starPivot', 'star:pivot')
  .joint('carrier', j.joint.revolute(), 'base:carrierPivot', 'carrier:pivot')
  .joint('pallet', j.joint.revolute(), 'carrier:palletPivot', 'pallet:pivot')
  .joint('latch', j.joint.revolute(), 'bridge:latchPivot', 'latch:pivot')

